function input(){let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touchMove.x,dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+touchMove.y;const l=Math.hypot(dx,dy);if(l>1){dx/=l;dy/=l}return[dx,dy]}
const grit=Array.from({length:190},()=>({x:Math.random(),y:Math.random(),r:rand(.5,2.4),a:rand(.025,.11)}));
function drawFloor(){ctx.fillStyle='#202a29';ctx.fillRect(0,0,W,H);const tile=82,ox=(elapsed*2)%tile;ctx.strokeStyle='#c9d2bd08';ctx.lineWidth=1;for(let x=-tile+ox;x<W+tile;x+=tile){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=-tile+ox;y<H+tile;y+=tile){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}for(const g of grit){ctx.fillStyle=`rgba(202,211,186,${g.a})`;ctx.fillRect(g.x*W,g.y*H,g.r,g.r)}
// Worn safety markings and abandoned supply crates
ctx.save();ctx.globalAlpha=.16;ctx.strokeStyle='#d2c997';ctx.lineWidth=2;for(let i=0;i<8;i++){let x=(i*167+90)%W,y=(i*239+130)%H;ctx.strokeRect(x,y,38,28);ctx.beginPath();ctx.moveTo(x+4,y+4);ctx.lineTo(x+34,y+24);ctx.moveTo(x+34,y+4);ctx.lineTo(x+4,y+24);ctx.stroke()}ctx.restore();
const grad=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.14,W/2,H/2,Math.max(W,H)*.75);grad.addColorStop(0,'#00000000');grad.addColorStop(1,'#080d0dcc');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H)}
function drawZombie(z){const bob=Math.sin(elapsed*5+z.phase)*1.5;ctx.save();ctx.translate(z.x,z.y+bob);ctx.rotate(Math.atan2(player.y-z.y,player.x-z.x));ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(-1,z.r*.45,z.r*1.12,z.r*.72,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=z.heavy?'#64614d':'#5f7761';ctx.lineWidth=z.heavy?7:5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-2,-5);ctx.lineTo(1,-z.r-4);ctx.moveTo(0,0);ctx.lineTo(9,z.r*.6);ctx.stroke();ctx.fillStyle=z.heavy?'#69664f':'#758b6c';ctx.beginPath();ctx.ellipse(0,0,z.r*.72,z.r*.9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=z.heavy?'#514c3e':'#564b3e';ctx.beginPath();ctx.arc(z.r*.25,-z.r*.62,z.r*.45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b8d675';ctx.fillRect(z.r*.28,-z.r*.73,3,2);ctx.fillRect(z.r*.59,-z.r*.73,3,2);ctx.fillStyle='#202521';ctx.fillRect(z.r*.31,-z.r*.28,z.r*.34,2);if(z.hit>0){ctx.strokeStyle='#ef7962';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,z.r+3,0,Math.PI*2);ctx.stroke()}if(z.hp<z.heavy?100:55){/* health is communicated by hit flashes */}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(0,8,17,11,0,0,Math.PI*2);ctx.fill();ctx.rotate(player.angle);ctx.fillStyle='#a5b89a';ctx.beginPath();ctx.arc(0,0,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#43574d';ctx.fillRect(-6,-9,14,18);ctx.fillStyle='#d5c9a8';ctx.beginPath();ctx.arc(2,0,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#242923';ctx.fillRect(4,-3,19,6);ctx.fillStyle='#b6c3a9';ctx.fillRect(12,-2,14,4);ctx.restore();if(player.invuln>0&&Math.floor(elapsed*20)%2===0){ctx.strokeStyle='#f17c67aa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x,player.y,20,0,Math.PI*2);ctx.stroke()}}
function draw(){ctx.save();let sx=screenShake?rand(-screenShake,screenShake):0,sy=screenShake?rand(-screenShake,screenShake):0;ctx.translate(sx,sy);drawFloor();for(const d of decal){ctx.fillStyle='#5e302833';ctx.beginPath();ctx.ellipse(d.x,d.y,d.r,d.r*.63,rand(-.2,.2),0,Math.PI*2);ctx.fill()}for(const z of zombies)drawZombie(z);for(const b of bullets){ctx.fillStyle=b.player?'#ffe5a0':'#ee7458';ctx.beginPath();ctx.arc(b.x,b.y,b.player?3:4,0,Math.PI*2);ctx.fill();ctx.strokeStyle=b.player?'#ffcd6c66':'#e9625066';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(b.x-b.vx*.018,b.y-b.vy*.018);ctx.lineTo(b.x,b.y);ctx.stroke()}drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/(p.max||.65),0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.restore();if(!shopOpen&&!paused&&active){ctx.strokeStyle='#d7e4c522';ctx.lineWidth=1;ctx.beginPath();ctx.arc(mouse.x,mouse.y,8,0,Math.PI*2);ctx.moveTo(mouse.x-13,mouse.y);ctx.lineTo(mouse.x-5,mouse.y);ctx.moveTo(mouse.x+5,mouse.y);ctx.lineTo(mouse.x+13,mouse.y);ctx.moveTo(mouse.x,mouse.y-13);ctx.lineTo(mouse.x,mouse.y-5);ctx.moveTo(mouse.x,mouse.y+5);ctx.lineTo(mouse.x,mouse.y+13);ctx.stroke()}}
function step(dt,now){elapsed+=dt;if(bannerTimer>0){bannerTimer-=dt;if(bannerTimer<=0)ui.banner.classList.remove('show')}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(!active||paused||shopOpen)return;
const [dx,dy]=input(),speed=220;player.x=clamp(player.x+dx*speed*dt,24,W-24);player.y=clamp(player.y+dy*speed*dt,35,H-35);if(!mobile){player.angle=Math.atan2(mouse.y-player.y,mouse.x-player.x)}else if(mouse.x||mouse.y){player.angle=Math.atan2(mouse.y-player.y,mouse.x-player.x)}player.invuln=Math.max(0,player.invuln-dt);if(player.reloadAt&&now>=player.reloadAt){const need=weapon().mag-player.ammo,take=Math.min(need,player.reserve);player.ammo+=take;player.reserve-=take;player.reloadAt=0;updateHUD()}if(mouse.down||fireHeld)shoot(now);
if(spawnLeft>0){spawnTimer-=dt;if(spawnTimer<=0){spawnZombie();spawnLeft--;spawnTimer=Math.max(.35,1.05-wave*.035)}}else if(zombies.length===0){between+=dt;if(between>2.5){wave++;beginWave();updateHUD()}}
for(const z of zombies){let dxp=player.x-z.x,dyp=player.y-z.y,d=Math.hypot(dxp,dyp)||1;if(d>z.r+15){z.x+=dxp/d*z.speed*dt;z.y+=dyp/d*z.speed*dt}z.attack-=dt;z.hit=Math.max(0,z.hit-dt);if(d<z.r+16&&z.attack<=0){damage(z.heavy?18:12);z.attack=.9}}
for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;if(b.player){for(let j=zombies.length-1;j>=0;j--){const z=zombies[j];if(dist(b.x-z.x,b.y-z.y)<z.r+3){z.hp-=b.damage;z.hit=.12;hit=true;if(z.hp<=0){killZombie(z);zombies.splice(j,1)}break}}}else if(dist(b.x-player.x,b.y-player.y)<16){damage(9);hit=true}if(hit||b.life<=0||b.x<-20||b.x>W+20||b.y<-20||b.y>H+20)bullets.splice(i,1)}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.vx){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96}if(p.life<=0)particles.splice(i,1)}screenShake=Math.max(0,screenShake-dt*20);updateHUD()}
function loop(now){if(!active&&!paused){draw();return}const dt=Math.min(.033,(now-last)/1000||0);last=now;step(dt,now);draw();requestAnimationFrame(loop)}

